BEGIN;
CREATE TABLE IF NOT EXISTS site_operating_cycles(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,site_id TEXT NOT NULL,business_date DATE NOT NULL,timezone TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('planned','open','degraded','halted','reconciled','closed')),plan JSONB NOT NULL,idempotency_key TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,site_id,business_date),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS operating_cycle_events(id BIGSERIAL PRIMARY KEY,cycle_id BIGINT NOT NULL REFERENCES site_operating_cycles(id),tenant_id TEXT NOT NULL,actor_id TEXT NOT NULL,event_type TEXT NOT NULL,from_state TEXT,to_state TEXT,idempotency_key TEXT,evidence_digest TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(cycle_id,idempotency_key));
CREATE TABLE IF NOT EXISTS equipment_telemetry_inbox(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,device_id TEXT NOT NULL,certificate_fingerprint TEXT NOT NULL,sequence BIGINT NOT NULL,idempotency_key TEXT NOT NULL,payload JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','accepted','quarantined')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,device_id,sequence),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS carwash_sync_jobs(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,provider TEXT NOT NULL CHECK(provider IN('pos','payment','equipment_iot','inventory','workforce','accounting')),idempotency_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','succeeded','failed','quarantined')),payload JSONB NOT NULL,requested_by TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,failure_code TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,provider,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_site_cycles_tenant_state ON site_operating_cycles(tenant_id,state,business_date);
COMMIT;
